INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('8be7c2c3f1d19c8bba06','What Are You Afraid Of? Acts 9:23-31','2022-02-13','https://www.buzzsprout.com/21035/10109913-what-are-you-afraid-of-acts-9-23-31.mp3','Fear can easily grip our hearts and paralyze us, but fear is also something God speaks clearly on. What are you afraid of? Today''s message helps us focus our fears on the only place worthy of fear... God. May today''s sermon lead you to trust in God more and walk in victory!','https://podcast.app/what-are-you-afraid-of-acts-923-31-e305759972','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
