INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('68d8a89db7e7fb594929','Receive the Holy Spirit','2022-01-16','https://www.buzzsprout.com/21035/9907612-receive-the-holy-spirit.mp3','In the book of Acts we see the church receive the Holy Spirit of God in a new way. What does this mean for Christians today? Do we need to receive the Holy Spirit? Pastor Daniel shares a message to encourage all of us to experience the gift of the Holy Spirit to the fullest measure.','https://podcast.app/receive-the-holy-spirit-e201939593','Pastor Daniel','description') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('819ab5d0bff105388d07','Is Your Heart Right Before God? Acts 8:1-25','2022-01-09','https://www.buzzsprout.com/21035/9854331-is-your-heart-right-before-god-acts-8-1-25.mp3','A man named Simon tried to buy the power of God in order to benefit from it himself. It is easy to see how he was trying to manipulate God for his own purposes. What may not be easy to see is how we can do the same thing today... trying to use God to benefit our own agendas. Is your heart right with God? Do you truly love God, or do you want God to be added to your life so you can benefit? Jesus is Lord. His church is victorious. His power is real. God loves you and the good news is that Jesus is the Messiah.','https://podcast.app/is-your-heart-right-before-god-acts-81-25-e201531596','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
