INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('435947bfbfb89b0c64b2','Step Back So God Steps In: Receiving the Holy Spirit','2021-10-03','https://www.buzzsprout.com/21035/9343757-step-back-so-god-steps-in-receiving-the-holy-spirit.mp3','We are to receive the gift of the Holy Spirit. Jesus promised the Spirit to us and delivered on his promise ten days after he ascended to heaven. Living by the power of the Holy Spirit is not an automatic part of the faith, but we are to step back and let God step in by receiving God''s gift. We will continue exploring the Holy Spirit for the next few weeks and discover his role and power in our lives.','https://podcast.app/step-back-so-god-steps-in-receiving-the-holy-spirit-e149928380','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
