INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('23d6c78adbf983e98f94','Jesus Is With You!','2021-09-12','https://www.buzzsprout.com/21035/9270110-jesus-is-with-you.mp3','What do you think Jesus is doing when you''re in the act of sin? Does he turn away, shake his head in disgust, or threaten to give up on you? No... he advocates for you. 1 John 2:1-2 show us the heart of Jesus that speaks up on our behalf when we sin. Certainly, God''s goal for our lives is for us to turn from sin in every way. John writes this NT letter so that we might not sin (1 John 2:1), but where our sin increases God''s grace increases even more. Praise Jesus, the righteous one!','https://podcast.app/jesus-is-with-you-e148892070','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
