INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('080b7ff521a768246bf8','I Am _______? (Loved)','2021-02-14','https://www.buzzsprout.com/21035/7892728-i-am-_______-loved.mp3','When you come to faith in Jesus you are born again. God''s Holy Spirit lives with you so that you have the DNA of Almighty God within you. And this is the God who spoke the world into existence, created the universe, and all the stars in the sky. He is all-powerful. And the one true God loves you! Romans 8:37-39 37 No, in all these things we are more than conquerors through him who loved us. 38 For I am convinced that neither death nor life, neither angels nor demons, neither the present nor the future, nor any powers, 39 neither height nor depth, nor anything else in all creation, will be able to separate us from the love of God that is in Christ Jesus our Lord. Today we want to speak this truth over our lives. “I AM LOVED.” Sometimes we will say this while believing it, and other times we will need to say it IN ORDER TO believe it.','https://podcast.app/i-am-_______-loved-e128842136','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('80f9789e6dfabf805b86','I Am _____? (blessed)','2021-02-07','https://www.buzzsprout.com/21035/7756096-i-am-_____-blessed.mp3','If you say "I am blessed" only when things are going well in your life, then you''re missing the power of knowing you are blessed no matter the circumstances of life. You are blessed because of who Jesus is and what he says about you. A blessing is "whatever brings you closer to God." Join us for the first sermon in our series "I Am ______?" How you speak about your life changes your life. So let the word of God fill in the blank for you.','https://podcast.app/i-am-_____-blessed-e128302497','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
