INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('68d1ee81dace60e0214b','Why Am I So Dissatisfied?','2021-01-17','https://www.buzzsprout.com/21035/7466779-why-am-i-so-dissatisfied.mp3','If you feel dissatisfied or if life isn''t what you thought it would be, then today''s message gives you the hope of finding your soul finding full satisfaction as God intends. Today''s music was powerful with Angela leading us again, and we had a special spoken word from Austin. We pray the Lord touches your heart and that you take a step of a faith in Jesus today.','https://podcast.app/why-am-i-so-dissatisfied-e127147412','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
