INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('c123af246c2a79d190d9','2021 Is Out Of Our Control But In God''s Hands','2021-01-03','https://www.buzzsprout.com/21035/7224214-2021-is-out-of-our-control-but-in-god-s-hands.mp3','Praise God! A new year is here, but a new date on the calendar does not guarantee better circumstances in our world. 2021 is not something we can control, but we can trust that God has the world in his hands. Prayer empowers us to flourish no matter the circumstances as it fills us with the presence of God''s Spirit. Today''s sermon encourages us to allow the Lord''s Prayer to guide our prayers, since our prayers are the lifeblood of our faith. THE LORD''s PRAYER Our Father who art in heaven, hallowed be Thy name. Thy kingdom come, Thy will be done on earth as it is in heaven. Give us this day our daily bread, and forgive us our trespasses as we forgive those who trespass against us. And lead us not into temptation, but deliver us from evil. For Thine is the kingdom and the power and the glory forever and ever. Amen! Every week our worship service will conclude with us saying the Lord''s Prayer together.','https://podcast.app/2021-is-out-of-our-control-but-in-gods-hands-e126052117','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
