INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('dd43d92462740173af27','"Share The Good News" - Our 5th Purpose','2020-05-18','https://www.buzzsprout.com/21035/3784319-share-the-good-news-our-5th-purpose.mp3','"Share The Good News" - Our 5th Purpose','https://podcast.app/share-the-good-news-our-5th-purpose-e97064222','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('39f54a0ae8e8b3b5451f','"Shaped For Serving God" - Our 4th Purpose','2020-05-11','https://www.buzzsprout.com/21035/3697533-shaped-for-serving-god-our-4th-purpose.mp3','Our 4th purpose in life is knowing we are "shaped for serving God." Nothing will fill the void in our life more than serving God. You can''t find lasting satisfaction in success, status, or your salary. Serving God is where we find ourselves satisfied. Join us in our 40 day journey as today marks our 28th day! Keep going! We are more than 2/3 of the way through it. Visit connectionnyc.com for more information about our church. May the grace of God which transcends all understanding guard your hearts and your minds in Christ Jesus! Watch the sermon online: https://www.youtube.com/watch?v=BwR36V8Mnxo','https://podcast.app/shaped-for-serving-god-our-4th-purpose-e96247354','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
