INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('bafd3830fac1e051c71f','Servant: When You Feel Like Putting People In Their Place (Philippians 2:5-11)','2020-02-16','https://www.buzzsprout.com/21035/2786149-servant-when-you-feel-like-putting-people-in-their-place-philippians-2-5-11.mp3','When you feel like proving yourself, setting someone straight, or putting people in their place then it''s the perfect time to look to Jesus! He has the power to put us in our place, but instead he uses his power to bring us to his place - to lift us up and to serve us! He laid down his life for our good and his glory. Allow the gospel to soothe your soul so that you can serve others as Jesus did!','https://podcast.app/servant-when-you-feel-like-putting-people-in-their-place-philippians-25-11-e87000565','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('55f9b4e48a1ff0a7cd7b','Servant: What Unites The People Of God? (Acts 2:42-47)','2020-02-09','https://www.buzzsprout.com/21035/2705422-servant-what-unites-the-people-of-god-acts-2-42-47.mp3','In a divided world, it is easier for division to creep into the church. So what unites the people of God in divisive times? Pastor Daniel looks at Acts 2:42-47 to go back to the beginning of the church for insight on how we unite as one for the glory of Jesus and the good of the world.','https://podcast.app/servant-what-unites-the-people-of-god-acts-242-47-e86086110','Pastor Daniel','description') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('89993790664ab2f1df4d','Servant: Fear, Defeat, Doubt: There''s No Room For You Here! (Psalm 27)','2020-02-03','https://www.buzzsprout.com/21035/2662549-servant-fear-defeat-doubt-there-s-no-room-for-you-here-psalm-27.mp3','When challenging times come, the enemy will send his weapons of fear, defeat, doubt, and more to try and finish us. This is an opportunity for us to run to the Lord quickly and experience his presence, power, and victory in our lives. The Lord is not absent during our struggles, but he is in them with us desiring to give us the comfort and strength we need to emerge victorious. Scripture: Psalm 27','https://podcast.app/servant-fear-defeat-doubt-theres-no-room-for-you-here-psalm-27-e85557212','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('1c443e744f2afbf4dc67','Servant: How Can I Truly Forgive Someone? (Matthew 18:21-35)','2020-01-27','https://www.buzzsprout.com/21035/2584357-servant-how-can-i-truly-forgive-someone-matthew-18-21-35.mp3','Have you ever struggled with forgiving someone? It''s safe to assume that most people have. It''s not easy to forgive, and sometimes it seems impossible. The gospel not only tells us to forgive others, but it changes our hearts to where we desire to extend forgiveness to others generously. Check out this message by Pastor Daniel McGhee!','https://podcast.app/servant-how-can-i-truly-forgive-someone-matthew-1821-35-e84634781','Pastor Daniel','description') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
