INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('97c50e17b31233356c11','Christmas at Connection - The Blessing Unveiled','2017-12-10','https://www.buzzsprout.com/21035/610059-christmas-at-connection-the-blessing-unveiled.mp3','God wants to bless you this Christmas in ways you may not expect and in a greater magnitude than you may expect. Pastor Daniel encourages us with a message from the Bible that leads us to expect more this Christmas by living under the powerful blessing of God.The Scripture reading is from: Genesis 12:1-3','https://podcast.app/christmas-at-connection-the-blessing-unveiled-e26417372','Pastor Daniel','description') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
