INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('8ba882758d22babd2981','Dreamer: Restoration With People','2017-11-05','https://www.buzzsprout.com/21035/590513-dreamer-restoration-with-people.mp3','Following last week sermon of Restoration with God, Pastor Larry shows us how Biblical follow up is restoration with people. Scripture is from Genesis 46','https://podcast.app/dreamer-restoration-with-people-e25166388','','') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('92ceceae031ee4149622','Dreamer: Restoration With God','2017-10-29','https://www.buzzsprout.com/21035/588366-dreamer-restoration-with-god.mp3','Pastor Daniel continues our sermon series Dreamer on the life of Joseph. Joseph confronts his brothers and Joesph''s father wants to see him. Its a great picture of the relationship God wants to have with us in restoring the relationship with himself.Te Scripture reading is from Genesis 45:16 - 28.','https://podcast.app/dreamer-restoration-with-god-e25166389','Pastor Daniel','description') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
INSERT INTO episodes(id,title,date,audio_url,description,link,speaker,speaker_source) VALUES('7f44281612a5bfbef46a','Dreamer: Divine Perspective','2017-10-15','https://www.buzzsprout.com/21035/580175-dreamer-divine-perspective.mp3','In this sermon, Pastor Daniel talks about having a Divine Perspective. Joseph had a different perspective and recognized God is in control even in difficult circumstances. God views us as his children and loves us that he even sent his only son for us to be sons and daughters in his kingdom.The Scripture reading is from Genesis 45:1-15','https://podcast.app/dreamer-divine-perspective-e24577141','Pastor Daniel','description') ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,audio_url=excluded.audio_url,description=excluded.description,link=excluded.link,speaker=excluded.speaker,speaker_source=excluded.speaker_source;
